{
  "summary": "On 2026-03-10 the edge returned 429 errors for search because the per‑pod rate limit was exceeded.",
  "likely_cause": "The edge‑gateway per‑pod limit of 100 requests per second (300 total across three pods) was hit by increased campaign traffic.",
  "confidence": "high",
  "claims": [
    {
      "text": "The edge limit allowed 300 requests per second total, about 100 per pod, and about 40 requests per second were refused on each pod.",
      "evidence_ids": ["RB-030#1"],
      "quote": "With 300 allowed, about 120 a second were refused... roughly 40 a second on each pod."
    },
    {
      "text": "Changing the number of edge pods or traffic distribution changes the effective limit.",
      "evidence_ids": ["RB-030#3"],
      "quote": "Per-pod limits add up. Change the number of edge pods, or how evenly traffic spreads across them, and the real limit changes with it."
    }
  ],
  "next_checks": [
    "Verify the current ConfigMap `edge-gateway-envoy` settings for the rate limit.",
    "Confirm the number of edge pods running at the time of the incident.",
    "Check if any recent rollout modified the limiter configuration."
  ]
}
